#/**********************************************************************************************************************
#  Description:  ETAS VFB Hooks implementation generator python script for timing measurements with Lauterbach TRACE32.
#  All VFB Hooks are filtered by SchM_Schedulable_ and Rte_Runnable_
#*********************************************************************************************************************/

#/**********************************************************************************************************************
# *	USER SPECIFIC SECTION:
# *	Change here AUTOSAR Project specific settings
# *********************************************************************************************************************/

# !! Change file paths here !!
fsrc=open("./Rte_Hook.h",'r')              # Generated by RTE
fdest=open("./Rte_Hook_Arti.c",'w')        # Generated by this Script
cmmdest=open("./rte_runnable.cmm",'w')     # Generated by this Script

# !! Change VFB hook prefix filters here !!
and_keywords = ['void Rte_']
or_keywords = ['Rte_Runnable_','SchM_Schedulable_']
components_keywords = ['EcuM_','ComM_','BswM_','Dcm_','Can_','Fee_','NvM_','Rtm_','Xcp_']

# *********************************************************************************************************************/

def GET_FuncName(str):  # grep the Runnables name, for example ")Runnables_name("
    sLoc=str.find(")")+1
    length=str[sLoc:].find("(")
    return ((str[sLoc:(sLoc+length)]).strip())

def GET_RunnableName(str):
    if or_keywords[0] in str:
        start=or_keywords[0]   #'Rte_Runnable_'
    elif or_keywords[1] in str:
        start=or_keywords[1]   #'SchM_Schedulable_'
    end='_Start('

    for component in components_keywords:
        if component in str:
            strnew = (str.split(start))[1].split(end)[0]
            strsplit = (strnew.split(component,1))
            str = start + strsplit[1] + end

    return ((str.split(start))[1].split(end)[0])

def File_Print(f,str):
    print(str)
    f.write(str+'\n')



# Write Header
File_Print(fdest, '/**********************************************************************************************************************')
File_Print(fdest, '	@Copyright: (C) 1989-2021 Lauterbach GmbH, licensed for use with TRACE32(R) only')
File_Print(fdest, '**********************************************************************************************************************/')
File_Print(fdest, '')


#pre writing to the file
File_Print(fdest, '')
File_Print(fdest, '/**********************************************************************************************************************')
File_Print(fdest, ' *  INCLUDES')
File_Print(fdest, ' *********************************************************************************************************************/')
File_Print(fdest, '#include "Std_Types.h"')
File_Print(fdest, '#include "Rte_Hook.h"')
File_Print(fdest, '#include "arti.h"')
File_Print(fdest, '')
File_Print(fdest, '/**********************************************************************************************************************')
File_Print(fdest, ' *  GLOBAL DATA TYPES AND STRUCTURES')
File_Print(fdest, ' *********************************************************************************************************************/')
File_Print(fdest, '')
File_Print(fdest, '/**********************************************************************************************************************')
File_Print(fdest, ' *  DEFINES')
File_Print(fdest, ' *********************************************************************************************************************/')
File_Print(fdest, '')
File_Print(fdest, '/**********************************************************************************************************************')
File_Print(fdest, ' *  COMPILER AND PLATFORM SPECIFIC DEFINES')
File_Print(fdest, ' *')
File_Print(fdest, ' *  Remove this section if not used.')
File_Print(fdest, ' *********************************************************************************************************************/')
File_Print(fdest, '#if defined(__GNUC__)')
File_Print(fdest, '/*')
File_Print(fdest, '* HIGHTEC V4.9.2.0 for TriCore Platform')
File_Print(fdest, '*/')
File_Print(fdest, '#define ATT_PROTECTED')
File_Print(fdest, '#endif')
File_Print(fdest, '')
File_Print(fdest, '#if defined(__TASKING__)')
File_Print(fdest, '/*')
File_Print(fdest, '* TASKING V6.2R1P3 for TriCore Platform')
File_Print(fdest, '*/')
File_Print(fdest, '#define ATT_PROTECTED __attribute__((protect))')
File_Print(fdest, '#endif')
File_Print(fdest, '')
File_Print(fdest, '/**********************************************************************************************************************')
File_Print(fdest, ' * VFB TRACING HOOK IMPLEMENTATIONS')
File_Print(fdest, ' *********************************************************************************************************************/')

totalHook=1

while True:
    line = fsrc.readline()
    if all(y in line for y in and_keywords):
        line=line.replace("void", "FUNC(void, RTE_APPL_CODE)",1) #replace the first 'void'->'FUNC(void, RTE_APPL_CODE)'
        if any(x in line for x in or_keywords):
            if ("_Start(" in line):
                line=line.rstrip(); #remove the ^M (carriage return)
                last_semi=line.rfind(";")
                line = line[:last_semi]+" ATT_PROTECTED {"+line[last_semi+1:] #replace ";" -> "{"
                funcName=GET_FuncName(line)
                File_Print(fdest, "#if !defined ("+funcName+")")
                File_Print(fdest, line)
                File_Print(fdest, "	/* #ID "+funcName+" "+str(totalHook)+"*/")
                File_Print(fdest, "\tARTI_TRACE(USER, AR_CP_RTE_RUNNABLE, ct, 0, RteRunnable_Start, "+str(totalHook)+");") # "ct" just as dummy
                File_Print(fdest, "}")
                File_Print(fdest, "#endif")
                cmmdest.write("TASK.CREATE.RUNNABLE "+funcName+" "+str(totalHook)+". "+'\"'+GET_RunnableName(funcName+"(")+'\"'+'\n')
                totalHook=totalHook+1
            elif ("_Return(" in line):
                line=line.rstrip(); #remove the ^M (carriage return)
                last_semi=line.rfind(";")
                line = line[:last_semi]+" ATT_PROTECTED {"+line[last_semi+1:] #replace ";" -> "{"
                funcName=GET_FuncName(line)
                File_Print(fdest, "#if !defined ("+funcName+")")
                File_Print(fdest, line)
                File_Print(fdest, "\tARTI_TRACE(USER, AR_CP_RTE_RUNNABLE, ct, 0, RteRunnable_Return, "+str(totalHook)+");") # "ct" just as dummy
                File_Print(fdest, "}")
                File_Print(fdest, "#endif")
                totalHook=totalHook
            print(line)
    if not line: break

#end writing
File_Print(fdest, '')
File_Print(fdest, '/**********************************************************************************************************************')
File_Print(fdest, ' *  END OF FILE: Rte_Hook_Arti.c')
File_Print(fdest, ' *********************************************************************************************************************/')
print('\nfile: "{0}" and generated hooks number: {1}.\n'.format(fdest.name, totalHook*2))

fsrc.close()
fdest.close()
cmmdest.close()

#/**********************************************************************************************************************
# *	END OF FILE: gen_vector_rte_hook.py
# **********************************************************************************************************************/
